def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])

    # If n is odd, we can't perfectly pair everyone
    if n % 2 != 0:
        return "-1\n"

    if n == 0:
        return "\n"

    # Build complete cost matrix
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j == i:
                continue
            costs[i][j] = row[idx]
            idx += 1

    # Create preference lists for each city (sorted by cost ascending)
    prefs = []
    for i in range(n):
        items = [(costs[i][j], j) for j in range(n) if i != j]
        items.sort()
        prefs.append(items)

    def is_stable(matching):
        """
        Check if matching is stable.
        A matching is stable if no blocking pair exists.
        A blocking pair is (i, j) where i!=j, matching[i]!=j, matching[j]!=i,
        and both i prefers j to matching[i], and j prefers i to matching[j].

        Player lower index = prefers that player
        Player higher index = cost to reach those paired to
        """
        for i in range(n):
            current = matching[i]
            if current == -1:
                continue

            # Check all potential partners for i
            for (c_j, j) in prefs[i]:
                if i == j:
                    continue
                if j == current:
                    continue
                if matching[j] == i or current == j:
                    continue

                # i prefers j over current (since sorted by cost)
                # Check if j also prefers i over its current match
                j_current = matching[j]
                if j_current == -1:
                    continue

                # j prefers i if cost[j][i] < cost[j][j_current]
                if costs[j][i] < costs[j][j_current]:
                    return False
        return True

    def try_stable_roommate_matching():
        """
        Find stable roommates matching.
        """
        matching = list(range(n))

        # Find blocking pairs and improve matching
        while True:
            blocked_p = False

            for i in range(n):
                for j, (c, k) in enumerate(prefs[i]):
                    if j == 0:
                        continue
                    # i's current match
                    i_match = matching[i]

                    # j's current match
                    j_m = matching[j]

                    # If j is matched with i or i with j
                    if i_match == j or j_m == i:
                        continue

                    # Both i and j have different partners
                    if i_match == j_m:
                        # Same partner check won't happen with n >= 2
                        continue

                    # Check if they're connected
                    if matching[j] == i:
                        continue

                    if costs[i][j] < costs[i][i_match] and costs[j][i] < costs[j][j_m]:
                        # Both prefer each other - blocking pair found
                        # Swap their participants
                        matching[i] = j
                        matching[j] = i

                        # Check if this helped or caused issues
                        return False  # Try again

                if blocked_p:
                    break
            blocked_p = True

        return matching

    # Try to build a stable matching using greedy approach
    matching = [-1] * n

    for i in range(n):
        if matching[i] != -1:
            continue
        # Find best available partner from preferences
        found = False
        for cost, j in prefs[i]:
            if matching[j] == -1:
                matching[i] = j
                matching[j] = i
                found = True
                break
        if found:
            continue

    # Check if the greedy matching is stable
    if is_stable(matching):
        result = []
        for i in range(n):
            if matching[i] != -1:
                result.append(str(matching[i] + 1))
            else:
                return "-1\n"
        return "\n".join(result) + "\n"

    # Try multiple strategies to find ANY stable matching
    def exhaustive_search():
        nonlocal matching
        import sys

        sys.setrecursionlimit(10000)

        def backtrack(path):
            if sum(1 for x in matching if x != matching[x]) == n:
                if is_stable(matching):
                    return True
                return False

            # Find unmatched
            idx = matching.index(-1) if -1 in matching else n

            if idx >= n:
                nonlocal matching
                return

            # Try all potential partners
            for (c_j, j) in prefs[idx]:
                if j == idx:
                    continue
                if matching[j] != -1:
                    continue

                # Assign matching
                matching[idx] = j
                matching[j] = idx

                if backtrack():
                    return True

                # Backtrack
                matching[idx] = -1
                matching[j] = -1

            return False

        return backtrack([])

