        edges.append((u, v, w, i + 1))  # i+1 for 1-indexed edge number

    # Build adjacency list
    adj = {}
    for u, v, w, idx in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    def bfs(start, end, removed_indices):
        if start == end:
            return False

        visited = [False] * (n + 1)
        visited[start] = True
        queue = [start]
        head = 0

