            u = queue[head]
            head += 1

            for v, w, edge_idx in adj.get(u, []):
                if edge_idx in removed_indices:
                    continue
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
                    if v == end:
                        return False

        return True

    # Check 0 edges - already disconnected?
    if not bfs(s, t, set()):
        return "0\n0\n"

    # Check 1 edge
