    successor = [-1] * n
    for i in range(k):
        x, y = map(int, lines[2 + i].split())
        successor[x - 1] = y - 1

    # Check for cycles in successor edges
    visited = [False] * n
    def has_cycle(start, s_arr):
        stack = [(start, False)]
        seen = set()
        while stack:
            node, added = stack.pop()
            if added:
                continue
            if node in seen:
                continue
            seen.add(node)
            stack.append((node, True))
            for child in s_arr[node]:
                if has_cycle(child, s_arr) or node in s_arr:
                    if child == -1:
                        continue
                    if child in seen:
                        continue
                    if node in s_arr and s_arr[node] == child:
                        return True
