            if depth[node] == i - 1:
                if visited_nodes[node]:
                    continue
                children_aggregated.append([node])
                visited_nodes[node] = True

        # Follow successor chain
        curr = root
        removed_chain = set()
        for _ in range(n):
            if curr == -1:
                break
            if curr in removed_chain:
