        if x == a[i-1]:
            if result[i-1] == 0:
                # Previous was in increasing, this must be in decreasing
                if dec == -float('inf') or x < dec:
                    result[i] = 1
                    dec = x
                else:
                    return "NO\n"
            else:
                # Previous was in decreasing, this must be in increasing
                if inc == -float('inf') or x > inc:
                    result[i] = 0
                    inc = x
                else:
                    return "NO\n"
            continue

        # Greedily assign to increasing if possible, otherwise decreasing
        if inc == -float('inf') or x > inc:
            result[i] = 0
            inc = x
        elif dec == -float('inf') or x < dec:
            result[i] = 1
            dec = x
        else:
