                if vr == r and vc == c:
                    continue
                if grid[vr][vc] == color:
                    return False
        return True

    def backtrack(idx):
        if idx == n * m:
            return True

        r, c = idx // m, idx % m

        if grid[r][c] > 0:
            if backtrack(idx + 1):
                return True
            return False

