            val = min(31, max(1, a[i] + random.randint(-20, 20)))
            b.append(val)

        # Fix non-harmony conflicts
        for i in range(n):
            if not is_harmony(b):
                # Find a coprime value to replace
                for new_val in candidates:
                    valid = True
                    for j in range(n):
                        if i != j and gcd(b[j], new_val) != 1:
                            valid = False
                            break
                    if valid:
                        b[i] = new_val
                        break
                else:
                    # Fallback: use 1
                    b[i] = 1

        # Try more aggressive fixes
        improved = True
        while improved:
            improved = False
            for i in range(n):
                if is_harmony(b):
                    break

                # Try to fix at position i
                for new_val in [1, *primes[:15]]:
                    valid = True
                    for j in range(n):
                        if i != j and gcd(b[j], new_val) != 1:
                            valid = False
                            break
                    if valid:
                        old = b[i]
                        b[i] = new_val
                        if calculate_cost(b, a) < best_cost:
                            best_cost = calculate_cost(b, a)
                            best_seq = b[:]
                        improved = True
                        break

        if is_harmony(b):
            cost = calculate_cost(b, a)
            if cost < best_cost:
                best_cost = cost
                best_seq = b[:]

    return best_seq

