    queue = deque([(frozenset(initial_set), [])])
    visited = {frozenset(initial_set)}

    result_path = []

    while queue:
        current_frozen, path = queue.popleft()
        current_set = set(current_frozen)

        if current_set == goal_set:
            result_path = path
            break

        if len(path) > 20000:
